/* ---------- core simulation ---------- */
class BossFightCore {
  constructor(){
    this.reset(1);
  }

  reset(seed){
    const num = Number(seed);
    const s = (Number.isFinite(num) ? Math.floor(num) : 1) >>> 0;
    this.seed = s;
    this._rng = mulberry32(s || 1);
    this.time = 0;
    this._accumulator = 0;
    this.started = false;
    this.paused = false;
    this.demo = false;
    this.outcome = null;
    this.outcomeAt = null;
    this.combo = 0;
    this.bestCombo = 0;
    this.score = 0;
    this.lastPressTime = -Infinity;
    this.player = { resolve: PLAYER_MAX_RESOLVE };

    const built = buildSchedule(this._rng);
    this.attacks = built.schedule;
    this.phase2Start = built.phase2Start;
    this.phase3Start = built.phase3Start;
    this.encounterEnd = built.encounterEnd;
    this._maxStability = built.totalBossDamage;
    this.boss = { stability: built.totalBossDamage };

    this.phase = 1;
    this._lastPhaseSeen = 1;
    this.effects = [];
    this._effectSeq = 0;
    this.demoCursor = 0;
  }

  start(){
    if(this.started) return;
    this.started = true;
    this.paused = false;
  }

  pause(){
    if(!this.started || this.outcome) return;
    this.paused = true;
  }

  resume(){
    if(!this.started || this.outcome) return;
    this.paused = false;
  }

  setDemo(enabled){
    this.demo = !!enabled;
  }

  press(){
    if(!this.started || this.paused || this.outcome) return false;
    const now = this.time;
    if(now - this.lastPressTime < PULSE_COOLDOWN){
      this._spawnEffect('deny', now, null);
      return false;
    }
    this.lastPressTime = now;
    let hitAny = false;
    for(const a of this.attacks){
      if(a.resolved || a.type === 'feint') continue;
      if(now >= a.telegraphStart && now >= a.windowStart && now <= a.windowEnd){
        a.resolved = true; a.resolvedAt = now; a.resolvedKind = 'parry';
        this.boss.stability = Math.max(0, this.boss.stability - a.bossDamage);
        this.combo += 1;
        this.bestCombo = Math.max(this.bestCombo, this.combo);
        this.score += 100 + this.combo*10;
        this._spawnEffect('parry', now, a);
        hitAny = true;
      }
    }
    if(!hitAny) this._spawnEffect('pulse', now, null);
    return hitAny;
  }

  step(ms){
    if(typeof ms !== 'number' || !isFinite(ms) || ms <= 0) return;
    if(!this.started || this.paused) return;
    this._accumulator += ms;
    let guard = 0;
    while(this._accumulator >= FIXED_DT && guard < 200000){
      this._tick(FIXED_DT);
      this._accumulator -= FIXED_DT;
      guard++;
    }
  }

  _tick(dt){
    if(!this.started || this.paused) return;
    this.time += dt;

    if(this.outcome){
      if(this.demo && (this.time - this.outcomeAt) >= DEMO_RESTART_DELAY){
        const nextSeed = (this.seed + 1) >>> 0;
        this.reset(nextSeed);
        this.demo = true;
        this.start();
      }
      return;
    }

    this.phase = this.time < this.phase2Start ? 1 : (this.time < this.phase3Start ? 2 : 3);
    if(this.phase !== this._lastPhaseSeen){
      this._spawnEffect('phaseShift', this.time, { phase: this.phase });
      this._lastPhaseSeen = this.phase;
    }

    for(const a of this.attacks){
      if(a.resolved) continue;
      if(this.time < a.telegraphStart) continue;
      if(a.type === 'feint'){
        if(this.time > a.fizzleTime){
          a.resolved = true; a.resolvedAt = this.time; a.resolvedKind = 'fizzle';
          this._spawnEffect('fizzle', this.time, a);
        }
      } else if(this.time > a.windowEnd){
        a.resolved = true; a.resolvedAt = this.time; a.resolvedKind = 'miss';
        this.player.resolve = Math.max(0, this.player.resolve - a.playerDamage);
        this.combo = 0;
        this._spawnEffect('miss', this.time, a);
      }
    }

    if(this.effects.length){
      this.effects = this.effects.filter(e => this.time < e.until);
    }

    if(this.demo) this._updateDemo();

    this._checkEncounterEnd();
  }

  _updateDemo(){
    if(this.outcome) return;
    while(this.demoCursor < this.attacks.length){
      const a = this.attacks[this.demoCursor];
      if(a.resolved){ this.demoCursor++; continue; }
      if(a.type === 'feint'){
        if(this.time > a.fizzleTime) this.demoCursor++;
        break;
      }
      const pressAt = (a.windowStart + a.windowEnd) / 2;
      if(this.time >= pressAt && (this.time - this.lastPressTime) >= PULSE_COOLDOWN){
        this.press();
      }
      if(this.time > a.windowEnd) this.demoCursor++;
      break;
    }
  }

  _checkEncounterEnd(){
    if(this.outcome) return;
    if(this.player.resolve <= 0){ this._endEncounter('failure'); return; }
    if(this.boss.stability <= 0){ this._endEncounter('success'); return; }
    if(this.time >= this.encounterEnd && this.attacks.every(a => a.resolved)){
      this._endEncounter(this.boss.stability <= 0 ? 'success' : 'failure');
    }
  }

  _endEncounter(result){
    this.outcome = result;
    this.outcomeAt = this.time;
    this._spawnEffect(result === 'success' ? 'victory' : 'defeat', this.time, null);
  }

  _spawnEffect(kind, at, attack){
    const life = EFFECT_LIFE[kind] || 600;
    this._effectSeq++;
    this.effects.push({
      seq: this._effectSeq, kind, at, until: at+life,
      type: attack ? (attack.type || null) : null,
      angle: attack && attack.angle != null ? attack.angle : 0,
      attackId: attack && attack.id != null ? attack.id : null,
      phase: attack && attack.phase != null ? attack.phase : this.phase,
    });
  }

  snapshot(){
    return {
      time: this.time,
      seed: this.seed,
      phase: this.phase,
      phase2Start: this.phase2Start,
      phase3Start: this.phase3Start,
      encounterEnd: this.encounterEnd,
      started: this.started,
      paused: this.paused,
      demo: this.demo,
      outcome: this.outcome,
      score: this.score,
      combo: this.combo,
      bestCombo: this.bestCombo,
      player: {
        resolve: this.player.resolve,
        maxResolve: PLAYER_MAX_RESOLVE,
        cooldownRemaining: Math.max(0, PULSE_COOLDOWN - (this.time - this.lastPressTime)),
      },
      boss: {
        name: BOSS_NAME,
        stability: this.boss.stability,
        maxStability: this._maxStability,
      },
      attacks: this.attacks
        .filter(a => !a.resolved && this.time >= a.telegraphStart)
        .map(a => ({
          id: a.id, type: a.type, phase: a.phase, angle: a.angle,
          telegraphStart: a.telegraphStart, impactTime: a.impactTime,
          windowStart: a.windowStart, windowEnd: a.windowEnd,
          fizzleTime: a.fizzleTime,
        })),
      scheduleTotal: this.attacks.length,
      scheduleResolved: this.attacks.filter(a => a.resolved).length,
    };
  }

  runSelfTest(){
    const tests = [];
    const record = (name, fn) => {
      try{
        const ok = fn();
        tests.push({ name, passed: ok === true });
      }catch(err){
        tests.push({ name, passed:false, detail:String(err && err.message || err) });
      }
    };

    record('deterministic reset produces identical snapshots for the same seed', () => {
      const a = createGame(); a.reset(4242); a.start(); a.step(3333);
      const b = createGame(); b.reset(4242); b.start(); b.step(3333);
      return JSON.stringify(a.snapshot()) === JSON.stringify(b.snapshot());
    });

    record('pause halts simulation time', () => {
      const g = createGame(); g.reset(5); g.start(); g.step(1000);
      const t1 = g.snapshot().time;
      g.pause(); g.step(2000);
      const t2 = g.snapshot().time;
      g.resume(); g.step(500);
      const t3 = g.snapshot().time;
      return t1 === t2 && t3 > t2;
    });

    record('phase advances from I to III over the encounter', () => {
      const g = createGame(); g.reset(9); g.start();
      const p1 = g.snapshot().phase;
      g.step(g.phase2Start + 200);
      const p2 = g.snapshot().phase;
      g.step((g.phase3Start - g.phase2Start) + 200);
      const p3 = g.snapshot().phase;
      return p1 === 1 && p2 === 2 && p3 === 3;
    });

    record('snapshot numeric fields stay finite', () => {
      const g = createGame(); g.reset(11); g.setDemo(true); g.start();
      for(let i=0;i<400;i++) g.step(50);
      const s = g.snapshot();
      const nums = [s.time, s.score, s.combo, s.bestCombo, s.player.resolve, s.player.cooldownRemaining, s.boss.stability, s.boss.maxStability];
      return nums.every(n => typeof n === 'number' && Number.isFinite(n));
    });

    record('demo autopilot reaches a success outcome', () => {
      const g = createGame(); g.reset(21); g.setDemo(true); g.start();
      let guard = 0;
      while(!g.snapshot().outcome && guard < 4000){ g.step(50); guard++; }
      return g.snapshot().outcome === 'success';
    });

    record('withholding input reaches a failure outcome', () => {
      const g = createGame(); g.reset(22); g.start();
      let guard = 0;
      while(!g.snapshot().outcome && guard < 4000){ g.step(50); guard++; }
      return g.snapshot().outcome === 'failure';
    });

    record('reset after an outcome restores a fresh run (instant restart)', () => {
      const g = createGame(); g.reset(23); g.start();
      let guard = 0;
      while(!g.snapshot().outcome && guard < 4000){ g.step(50); guard++; }
      g.reset(23);
      const s = g.snapshot();
      return s.time === 0 && s.outcome === null && s.phase === 1 && !s.started &&
        s.boss.stability === s.boss.maxStability && s.player.resolve === s.player.maxResolve;
    });

    record('demo mode drives the real gameplay state, not a canned animation', () => {
      const g = createGame(); g.reset(24); g.setDemo(true); g.start();
      const before = g.snapshot();
      for(let i=0;i<80;i++) g.step(50);
      const after = g.snapshot();
      const sameShape = Object.keys(before).every(k => k in after) &&
        Object.keys(before.boss).every(k => k in after.boss) &&
        Object.keys(before.player).every(k => k in after.player);
      return sameShape && after.time > before.time &&
        after.boss.stability < before.boss.stability && after.score > before.score;
    });

    const passed = tests.every(t => t.passed);
    return { passed, tests };
  }
}

function createGame(){ return new BossFightCore(); }

const game = createGame();
game.reset(1);
window.__BOSS_FIGHT__ = game;

try{
  const selfTestResult = game.runSelfTest();
  if(selfTestResult.passed){
    console.info('[BossFight] self-test passed', selfTestResult);
  }else{
    console.warn('[BossFight] self-test reported failures', selfTestResult);
  }
}catch(err){
  console.warn('[BossFight] self-test threw', err);
}

})();

