function regenerateVisuals(seed){
  const vrng = mulberry32((seed ^ 0x9e3779b9) >>> 0);
  crackLines = [];
  for(let i=0;i<5;i++){
    const startAngle = -70 + vrng()*140;
    let x = EYE_POS.x + Math.cos(startAngle*Math.PI/180)*30;
    let y = EYE_POS.y + Math.sin(startAngle*Math.PI/180)*30 + 12;
    const pts = [{x,y}];
    for(let s=0;s<5;s++){
      x += (vrng()-0.5)*46;
      y += 14 + vrng()*18;
      pts.push({x,y});
    }
    crackLines.push(pts);
  }
  stars = [];
  for(let i=0;i<60;i++){
    stars.push({ x: vrng()*LOGICAL_W, y: vrng()*LOGICAL_H*0.55, r: 0.4+vrng()*1.1, phase: vrng()*Math.PI*2 });
  }
  lastVisualSeed = seed;
}

