let audioCtx = null, masterGain = null, muted = false;
function ensureAudio(){
  if(audioCtx){
    if(audioCtx.state === 'suspended') audioCtx.resume().catch(()=>{});
    return;
  }
  try{
    const Ctor = window.AudioContext || window.webkitAudioContext;
    if(!Ctor) return;
    audioCtx = new Ctor();
    masterGain = audioCtx.createGain();
    masterGain.gain.value = muted ? 0 : 0.7;
    masterGain.connect(audioCtx.destination);
  }catch(err){ audioCtx = null; }
}
function toggleMute(){
  muted = !muted;
  btnMute.setAttribute('aria-pressed', String(muted));
  btnMute.textContent = muted ? 'Unmute' : 'Mute';
  if(masterGain) masterGain.gain.value = muted ? 0 : 0.7;
}
function tone(freq, dur, type, peak, delay){
  if(!audioCtx || muted) return;
  try{
    const t0 = audioCtx.currentTime + (delay || 0);
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = type || 'sine';
    osc.frequency.setValueAtTime(freq, t0);
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.001, peak || 0.3), t0+0.015);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0+dur);
    osc.connect(gain); gain.connect(masterGain);
    osc.start(t0); osc.stop(t0+dur+0.02);
  }catch(err){ /* ignore audio scheduling errors */ }
}
function noiseBurst(dur, peak, filterFreq){
  if(!audioCtx || muted) return;
  try{
    const bufferSize = Math.max(1, Math.floor(audioCtx.sampleRate*dur));
    const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
    const data = buffer.getChannelData(0);
    for(let i=0;i<bufferSize;i++) data[i] = (Math.random()*2-1)*(1-i/bufferSize);
    const src = audioCtx.createBufferSource();
    src.buffer = buffer;
    const filter = audioCtx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = filterFreq || 1200;
    const gain = audioCtx.createGain();
    gain.gain.value = peak || 0.3;
    src.connect(filter); filter.connect(gain); gain.connect(masterGain);
    src.start();
  }catch(err){ /* ignore audio scheduling errors */ }
}
