/* ---------- particles (cosmetic layer, not gameplay state) ---------- */
let particles = [];
let lastParticleSeqSeen = 0;
let lastParticleTs = null;
function spawnParticlesForEffects(){
  for(const e of game.effects){
    if(e.seq <= lastParticleSeqSeen) continue;
    if(e.kind === 'parry'){
      const count = reducedMotion ? 4 : 14;
      for(let i=0;i<count;i++){
        const a = Math.random()*Math.PI*2;
        const speed = 60+Math.random()*140;
        particles.push({ x:PLAYER_POS.x, y:PLAYER_POS.y-10, vx:Math.cos(a)*speed, vy:Math.sin(a)*speed, life:0, maxLife:500+Math.random()*300, color:'255,246,216', size:2+Math.random()*2 });
      }
    } else if(e.kind === 'miss'){
      const count = reducedMotion ? 3 : 8;
      for(let i=0;i<count;i++){
        const a = Math.random()*Math.PI*2;
        particles.push({ x:PLAYER_POS.x, y:PLAYER_POS.y, vx:Math.cos(a)*80, vy:Math.sin(a)*80-40, life:0, maxLife:400, color:'255,93,108', size:2+Math.random()*2 });
      }
    }
  }
  if(game.effects.length) lastParticleSeqSeen = game.effects[game.effects.length-1].seq;
}
function updateParticles(){
  const now = performance.now();
  const dt = lastParticleTs == null ? 16 : Math.min(48, now-lastParticleTs);
  lastParticleTs = now;
  spawnParticlesForEffects();
  if(game.paused) return;
  for(const pt of particles){
    pt.life += dt;
    pt.x += pt.vx*dt/1000;
    pt.y += pt.vy*dt/1000;
    pt.vy += 90*dt/1000;
  }
  particles = particles.filter(pt => pt.life < pt.maxLife);
}
function drawParticles(){
  for(const pt of particles){
    const a = 1-pt.life/pt.maxLife;
    ctx.fillStyle = `rgba(${pt.color},${a})`;
    ctx.beginPath();
    ctx.arc(pt.x, pt.y, pt.size, 0, Math.PI*2);
    ctx.fill();
  }
}

/* ---------- rendering ---------- */
function phaseColor(phase, alpha){
  const c = phase===1 ? '232,184,75' : phase===2 ? '255,138,77' : '168,121,255';
  return `rgba(${c},${alpha})`;
}

function drawBackground(t){
  ctx.save();
  const grad = ctx.createRadialGradient(240,200,40,240,320,420);
  grad.addColorStop(0, phaseColor(game.phase,0.16));
  grad.addColorStop(1, 'rgba(5,6,16,0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0,0,LOGICAL_W,LOGICAL_H);
  for(const s of stars){
    const tw = reducedMotion ? 0.5 : 0.5+0.5*Math.sin(t*0.0015+s.phase);
    ctx.globalAlpha = 0.25+tw*0.35;
    ctx.fillStyle = '#cfd6ff';
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, Math.PI*2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  ctx.restore();
}

function drawArenaFloor(t){
  ctx.save();
  ctx.translate(ARENA_CENTER.x, ARENA_CENTER.y);
  for(let i=3;i>=1;i--){
    const rx = ARENA_RX*(i/3), ry = ARENA_RY*(i/3);
    ctx.beginPath();
    ctx.ellipse(0,0,rx,ry,0,0,Math.PI*2);
    ctx.strokeStyle = `rgba(232,184,75,${0.08+0.04*i})`;
    ctx.lineWidth = 1;
    ctx.stroke();
  }
  ctx.save();
  const rot = reducedMotion ? 0 : t*0.00004;
  ctx.rotate(rot);
  ctx.beginPath();
  for(let i=0;i<24;i++){
    const a = (i/24)*Math.PI*2;
    ctx.moveTo(Math.cos(a)*ARENA_RX*0.3, Math.sin(a)*ARENA_RY*0.3);
    ctx.lineTo(Math.cos(a)*ARENA_RX, Math.sin(a)*ARENA_RY);
  }
  ctx.strokeStyle = 'rgba(232,184,75,0.06)';
  ctx.stroke();
  ctx.restore();
  ctx.restore();
}

function drawBoss(t){
  const bob = reducedMotion ? 0 : Math.sin(t*0.001)*4;
  ctx.save();
  ctx.translate(BOSS_ANCHOR.x, BOSS_ANCHOR.y+bob);

  ctx.save();
  ctx.rotate(reducedMotion ? 0 : t*0.00015);
  ctx.beginPath();
  ctx.arc(0,10,150,0,Math.PI*2);
  ctx.strokeStyle = phaseColor(game.phase,0.12);
  ctx.lineWidth = 2;
  ctx.setLineDash([2,14]);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.restore();

  ctx.beginPath();
  ctx.moveTo(-170,170);
  ctx.quadraticCurveTo(-190,40,-90,-30);
  ctx.quadraticCurveTo(-40,-70,0,-72);
  ctx.quadraticCurveTo(40,-70,90,-30);
  ctx.quadraticCurveTo(190,40,170,170);
  ctx.quadraticCurveTo(0,130,-170,170);
  ctx.closePath();
  const bodyGrad = ctx.createLinearGradient(0,-72,0,170);
  bodyGrad.addColorStop(0,'#2b2438');
  bodyGrad.addColorStop(1,'#161225');
  ctx.fillStyle = bodyGrad;
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.strokeStyle = 'rgba(232,184,75,0.35)';
  ctx.stroke();

  for(const line of crackLines){
    ctx.beginPath();
    ctx.moveTo(line[0].x-BOSS_ANCHOR.x, line[0].y-BOSS_ANCHOR.y);
    for(let i=1;i<line.length;i++) ctx.lineTo(line[i].x-BOSS_ANCHOR.x, line[i].y-BOSS_ANCHOR.y);
    const glow = reducedMotion ? 0.45 : 0.35+0.25*Math.sin(t*0.004+line[0].x);
    ctx.strokeStyle = phaseColor(game.phase, glow);
    ctx.lineWidth = 1.4;
    ctx.stroke();
  }

  const eyeOpen = game.phase===1 ? 0.55 : game.phase===2 ? 0.85 : 1;
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(0,18,46,30*eyeOpen,0,0,Math.PI*2);
  ctx.clip();
  ctx.fillStyle = '#100b18';
  ctx.fillRect(-60,-20,120,80);
  const eyeGrad = ctx.createRadialGradient(0,18,4,0,18,46);
  eyeGrad.addColorStop(0, phaseColor(game.phase,1));
  eyeGrad.addColorStop(0.55, phaseColor(game.phase,0.5));
  eyeGrad.addColorStop(1,'rgba(0,0,0,0.6)');
  ctx.fillStyle = eyeGrad;
  const pulseR = 16+(reducedMotion?0:Math.sin(t*0.003)*2);
  ctx.beginPath();
  ctx.arc(0,18,pulseR,0,Math.PI*2);
  ctx.fill();
  ctx.fillStyle = '#0a0710';
  ctx.beginPath();
  ctx.ellipse(0,18,6,14,0,0,Math.PI*2);
  ctx.fill();
  ctx.restore();
  ctx.beginPath();
  ctx.ellipse(0,18,46,30*eyeOpen,0,0,Math.PI*2);
  ctx.strokeStyle = phaseColor(game.phase,0.7);
  ctx.lineWidth = 2;
  ctx.stroke();

  ctx.restore();
}

function curvePoint(x0,y0,cx,cy,x1,y1,tt){
  const u = 1-tt;
  return { x: u*u*x0+2*u*tt*cx+tt*tt*x1, y: u*u*y0+2*u*tt*cy+tt*tt*y1 };
}
function drawCurve(x0,y0,cx,cy,x1,y1,upTo){
  ctx.beginPath();
  ctx.moveTo(x0,y0);
  const steps = 18;
  for(let i=1;i<=steps;i++){
    const tt = (i/steps)*upTo;
    const p = curvePoint(x0,y0,cx,cy,x1,y1,tt);
    ctx.lineTo(p.x,p.y);
  }
  ctx.stroke();
}
function attackProgress(a,t){
  if(a.type==='feint') return clamp((t-a.telegraphStart)/(a.fizzleTime-a.telegraphStart),0,1);
  return clamp((t-a.telegraphStart)/(a.impactTime-a.telegraphStart),0,1);
}

function drawAttacks(t){
  for(const a of game.attacks){
    if(t < a.telegraphStart) continue;
    const justResolved = a.resolved && (t-a.resolvedAt) < 260;
    if(a.resolved && !justResolved) continue;
    const p = attackProgress(a,t);
    const rad = a.angle*Math.PI/180;
    const originX = EYE_POS.x + Math.sin(rad)*40;
    const originY = EYE_POS.y - 10;
    const targetX = PLAYER_POS.x + Math.sin(rad)*14;
    const targetY = PLAYER_POS.y - 20;
    const cx = originX + (targetX-originX)*0.5 + Math.sin(rad)*30;
    const cy = originY + (targetY-originY)*0.35;

    if(a.type === 'feint'){
      const fp = p<0.7 ? p/0.7 : 1-(p-0.7)/0.3;
      ctx.save();
      ctx.globalAlpha = 0.2+0.22*Math.abs(Math.sin(t*0.02))*fp;
      ctx.strokeStyle = '#8fd7ff';
      ctx.lineWidth = 2;
      drawCurve(originX,originY,cx,cy,targetX,targetY, Math.max(0.02,fp));
      ctx.restore();
      continue;
    }

    if(a.type === 'eclipse' && !a.resolved){
      ctx.save();
      ctx.globalAlpha = 0.1+0.16*p;
      const grad = ctx.createRadialGradient(PLAYER_POS.x,PLAYER_POS.y-40,10,PLAYER_POS.x,PLAYER_POS.y-40,220);
      grad.addColorStop(0,'rgba(168,121,255,0.5)');
      grad.addColorStop(1,'rgba(168,121,255,0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(PLAYER_POS.x,PLAYER_POS.y-40,220*p,0,Math.PI*2);
      ctx.fill();
      ctx.restore();
    }

    const color = a.type==='eclipse' ? '168,121,255' : a.type==='shard' ? '255,154,77' : '232,184,75';
    ctx.save();
    if(a.resolvedKind === 'parry'){
      const fade = clamp(1-(t-a.resolvedAt)/260,0,1);
      ctx.globalAlpha = fade;
      ctx.strokeStyle = `rgba(255,255,255,${fade})`;
      ctx.lineWidth = 4;
      drawCurve(originX,originY,cx,cy,targetX,targetY,1);
    } else if(a.resolvedKind === 'miss'){
      const fade = clamp(1-(t-a.resolvedAt)/260,0,1);
      ctx.globalAlpha = fade;
      ctx.strokeStyle = `rgba(255,90,100,${fade})`;
