import { chromium } from 'playwright';
import path from 'path';

const filePath = 'file://' + path.resolve('index.html');

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 900, height: 1000 } });

const consoleMessages = [];
page.on('console', msg => {
  consoleMessages.push({ type: msg.type(), text: msg.text() });
});
page.on('pageerror', err => {
  consoleMessages.push({ type: 'pageerror', text: String(err) });
});

await page.goto(filePath);
await page.waitForTimeout(500);

console.log('--- Console messages after load ---');
for (const m of consoleMessages) console.log(m.type, ':', m.text);

// Check title
const title = await page.title();
console.log('Title:', JSON.stringify(title));
const h1 = await page.textContent('h1');
console.log('H1:', JSON.stringify(h1));

// Run self-test via exposed API
const selfTest = await page.evaluate(() => window.__BOSS_FIGHT__.runSelfTest());
console.log('--- Self test ---');
console.log(JSON.stringify(selfTest, null, 2));

// Deterministic run: reset+start+demo, step until outcome, measure time
const demoResult = await page.evaluate(() => {
  const g = window.__BOSS_FIGHT__;
  g.reset(777);
  g.setDemo(true);
  g.start();
  let guard = 0;
  while (!g.snapshot().outcome && guard < 5000) {
    g.step(50);
    guard++;
  }
  return g.snapshot();
});
console.log('--- Demo run result (seed 777) ---');
console.log('outcome:', demoResult.outcome, 'time(s):', (demoResult.time/1000).toFixed(2), 'phase:', demoResult.phase, 'score:', demoResult.score);

// Failure run (no input)
const failResult = await page.evaluate(() => {
  const g = window.__BOSS_FIGHT__;
  g.reset(888);
  g.start();
  let guard = 0;
  while (!g.snapshot().outcome && guard < 5000) {
    g.step(50);
    guard++;
  }
  return g.snapshot();
});
console.log('--- No-input run result (seed 888) ---');
console.log('outcome:', failResult.outcome, 'time(s):', (failResult.time/1000).toFixed(2));

await page.screenshot({ path: '/tmp/boss-fight-ready.png' });

// Reset to a live visible run and click Begin, then let real rAF drive briefly
await page.evaluate(() => { window.__BOSS_FIGHT__.reset(1); });
await page.click('#btnBegin');
await page.waitForTimeout(1200);
await page.screenshot({ path: '/tmp/boss-fight-playing.png' });

// trigger a press near expected time via keyboard
await page.keyboard.press('Space');
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/boss-fight-press.png' });

console.log('--- Console messages after interaction ---');
for (const m of consoleMessages) console.log(m.type, ':', m.text);

await browser.close();

