import { chromium } from 'playwright';

const filePath = 'file:///Users/melvynx/Developer/experiments/benchmarks/benchmarks/one-button-boss-fight/2026-07-16-cc-claude-sonnet-5-2/index.html';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 900, height: 1000 } });
const errors = [];
page.on('pageerror', e => errors.push(String(e)));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });

await page.goto(filePath);
await page.waitForTimeout(300);

// Drive the LIVE game via step() directly to specific phases, then let rAF render a frame.
async function gotoTime(ms, seed = 42, demo = true) {
  await page.evaluate(({ ms, seed, demo }) => {
    const g = window.__BOSS_FIGHT__;
    g.reset(seed);
    g.setDemo(demo);
    g.start();
    let guard = 0;
    while (g.snapshot().time < ms && !g.snapshot().outcome && guard < 5000) {
      g.step(50);
      guard++;
    }
  }, { ms, seed, demo });
  await page.waitForTimeout(100); // let one rAF frame render
}

await gotoTime(3000);
await page.screenshot({ path: '/tmp/v-phase1.png' });

await gotoTime(20000);
await page.screenshot({ path: '/tmp/v-phase2.png' });

await gotoTime(37000);
await page.screenshot({ path: '/tmp/v-phase3.png' });

// run to completion (success)
await page.evaluate(() => {
  const g = window.__BOSS_FIGHT__;
  g.reset(42);
  g.setDemo(true);
  g.start();
  let guard = 0;
  while (!g.snapshot().outcome && guard < 5000) { g.step(50); guard++; }
});
await page.waitForTimeout(150);
await page.screenshot({ path: '/tmp/v-victory.png' });

// failure state
await page.evaluate(() => {
  const g = window.__BOSS_FIGHT__;
  g.reset(99);
  g.start();
  let guard = 0;
  while (!g.snapshot().outcome && guard < 5000) { g.step(50); guard++; }
});
await page.waitForTimeout(150);
await page.screenshot({ path: '/tmp/v-defeat.png' });

// paused state
await page.evaluate(() => {
  const g = window.__BOSS_FIGHT__;
  g.reset(5);
  g.start();
  g.step(2000);
  g.pause();
});
await page.waitForTimeout(150);
await page.screenshot({ path: '/tmp/v-paused.png' });

// ready state fresh
await page.evaluate(() => window.__BOSS_FIGHT__.reset(1));
await page.waitForTimeout(150);
await page.screenshot({ path: '/tmp/v-ready.png' });

// mobile narrow viewport
await page.setViewportSize({ width: 375, height: 700 });
await page.waitForTimeout(150);
await page.screenshot({ path: '/tmp/v-mobile.png' });

console.log('Errors captured:', errors.length ? errors : 'none');
await browser.close();

