const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + String(e)));
page.on('console', m => { if (m.type() === 'error') errors.push('console.error: ' + m.text()); });

await page.goto(filePath);
await page.waitForTimeout(300);

// Click Begin (real DOM click), then real-time play with clicks on canvas
await page.click('#btnBegin');
for (let i = 0; i < 6; i++) {
  await page.waitForTimeout(700);
  await page.click('#scene');
}
await page.waitForTimeout(500);

const midSnap = await page.evaluate(() => window.__BOSS_FIGHT__.snapshot());
console.log('Mid-play snapshot: time=%s phase=%s score=%s resolve=%s/%s outcome=%s',
  midSnap.time.toFixed(0), midSnap.phase, midSnap.score, midSnap.player.resolve, midSnap.player.maxResolve, midSnap.outcome);

// Test pause via button, ensure sim time freezes
await page.click('#btnPause');
const t1 = (await page.evaluate(() => window.__BOSS_FIGHT__.snapshot())).time;
await page.waitForTimeout(600);
const t2 = (await page.evaluate(() => window.__BOSS_FIGHT__.snapshot())).time;
console.log('Pause check: t1=%s t2=%s frozen=%s', t1.toFixed(1), t2.toFixed(1), t1 === t2);
await page.click('#btnResume');
await page.waitForTimeout(300);

// Test restart button (instant restart)
await page.click('#btnRestart');
await page.waitForTimeout(200);
const afterRestart = await page.evaluate(() => window.__BOSS_FIGHT__.snapshot());
console.log('After restart: time=%s outcome=%s started=%s', afterRestart.time.toFixed(1), afterRestart.outcome, afterRestart.started);

// Test mute toggle doesn't throw
await page.click('#btnMute');
await page.click('#btnMute');

// Test demo toggle from UI
await page.click('#btnDemo');
await page.waitForTimeout(1500);
const demoSnap = await page.evaluate(() => window.__BOSS_FIGHT__.snapshot());
console.log('Demo via UI: demo=%s time=%s score=%s', demoSnap.demo, demoSnap.time.toFixed(0), demoSnap.score);

// Space-focused-on-button guard: focus the restart button and press space, ensure no gameplay press happens (score/time frozen aside from normal tick)
await page.click('#btnDemo'); // turn demo off, resets to ready
await page.click('#btnBegin');
await page.focus('#btnPause');
const beforeSpace = await page.evaluate(() => window.__BOSS_FIGHT__.snapshot().player.cooldownRemaining);
await page.keyboard.press('Space'); // should toggle Pause button (focused), not fire press()
await page.waitForTimeout(100);
const afterSpace = await page.evaluate(() => window.__BOSS_FIGHT__.snapshot());
console.log('Space-on-focused-button: paused=%s (expect true, since Pause button was activated)', afterSpace.paused);

// resize test
await page.setViewportSize({ width: 500, height: 900 });
await page.waitForTimeout(200);
await page.setViewportSize({ width: 900, height: 1000 });
await page.waitForTimeout(200);

console.log('Errors captured:', errors.length ? errors : 'none');
await browser.close();

