const filePath = 'file:///Users/melvynx/Developer/experiments/benchmarks/benchmarks/one-button-boss-fight/2026-07-16-cc-claude-sonnet-5-2/index.html';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 900, height: 1000 } });
const errors = [];
page.on('pageerror', e => errors.push(String(e)));

await page.goto(filePath);
await page.waitForTimeout(200);
await page.click('#btnBegin');
await page.waitForTimeout(300);

await page.focus('#btnPause');
const activeTagBefore = await page.evaluate(() => document.activeElement.tagName);
const beforePressCount = await page.evaluate(() => {
  const g = window.__BOSS_FIGHT__;
  g.__testPressCount = g.__testPressCount || 0;
  return g.lastPressTime;
});
await page.keyboard.press('Space');
await page.waitForTimeout(100);
const afterLastPressTime = await page.evaluate(() => window.__BOSS_FIGHT__.lastPressTime);
const pausedNow = await page.evaluate(() => window.__BOSS_FIGHT__.paused);

console.log('active element tag while focused:', activeTagBefore);
console.log('lastPressTime before:', beforePressCount, 'after:', afterLastPressTime, 'unchanged (no stray pulse):', beforePressCount === afterLastPressTime);
console.log('paused after space-on-focused-pause-button:', pausedNow);

// now blur (click canvas area isn't ideal since it presses); instead use document.body focus via evaluate
await page.evaluate(() => document.activeElement.blur());
await page.waitForTimeout(50);
const beforeLastPress2 = await page.evaluate(() => window.__BOSS_FIGHT__.lastPressTime);
await page.keyboard.press('Space');
await page.waitForTimeout(50);
const afterLastPress2 = await page.evaluate(() => window.__BOSS_FIGHT__.lastPressTime);
console.log('with no button focused, space DID fire a pulse (lastPressTime changed):', beforeLastPress2 !== afterLastPress2);

console.log('errors:', errors.length ? errors : 'none');
await browser.close();
